import pytest

from shop.cart import Cart
from shop.pricing import apply_discount, average_price


def test_discount_returns_price_after_discount():
    assert apply_discount(200, 25) == pytest.approx(150)


def test_fractional_discount():
    assert apply_discount(80, 12.5) == pytest.approx(70)


def test_empty_average_is_zero():
    assert average_price([]) == 0.0


def test_cart_total_uses_discounted_price():
    cart = Cart()
    cart.add('lamp', 40)
    assert cart.total(discount_percent=50) == pytest.approx(20)
